-- ════════════════════════════════════════════════════════════════════
-- Zondagopenstelling: startposities gecorrigeerd (input wethouder 19-11-2026)
--   SGP en CU: tegen zondagopenstelling (principieel)
--   CDA: voor openstelling in Holten tussen 13.00 en 18.00 uur (= huidige situatie)
--   GB, PRO, FvD, VVD: voor openstelling in beide kernen
-- Het raadsvoorstel (alles blijft zoals het is) verandert niet. GB zit
-- daardoor klem tussen eigen wens en coalitieakkoord ("twijfel").
-- ════════════════════════════════════════════════════════════════════

update public.sp_dossiers set inhoud = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(inhoud,
  '{fractie_hints}', $j${
    "sgp": {"neiging": "voor", "aandachtspunt": "de zondagsrust: de SGP is principieel tegen winkels die op zondag open zijn, ook in Holten; het coalitieakkoord zorgt er in elk geval voor dat het niet verder gaat", "voorwaarde": "geen enkele verruiming van de zondagopenstelling", "fallback_standpunt": "De SGP-fractie is principieel tegen zondagopenstelling, ook in Holten. In het coalitieakkoord is afgesproken dat de situatie niet verder wordt verruimd. Daarom steunt de fractie dit voorstel: verder dan dit kan wat ons betreft niet."},
    "cda": {"neiging": "voor", "aandachtspunt": "openstelling in Holten tussen 13.00 en 18.00 uur is een goed compromis tussen zondagsrust, toerisme en ondernemers; het coalitieakkoord nakomen", "voorwaarde": "de huidige openingstijden in Holten, 13.00 tot 18.00 uur, blijven zoals ze zijn", "fallback_standpunt": "Het CDA vindt de huidige regeling in Holten, open van 13.00 tot 18.00 uur, een goed evenwicht tussen rust en ruimte. Zo staat het ook in het coalitieakkoord. De fractie steunt dit voorstel."},
    "gb": {"neiging": "twijfel", "aandachtspunt": "GB is eigenlijk voor zondagopenstelling in beide kernen, maar heeft in het coalitieakkoord afgesproken dat de huidige situatie blijft", "voorwaarde": "perspectief op ruimere openstelling na deze raadsperiode, bijvoorbeeld via een evaluatie, zonder het coalitieakkoord nu te breken", "fallback_standpunt": "Gemeentebelang vindt dat winkels in Rijssen en Holten op zondag open zouden mogen. Maar we hebben in het coalitieakkoord iets anders afgesproken, en afspraak is afspraak. Dat schuurt."},
    "cu": {"neiging": "voor", "aandachtspunt": "de zondagsrust, ook als bescherming van werknemers; de CU is principieel tegen zondagopenstelling en steunt daarom elk voorstel dat verdere verruiming tegenhoudt", "voorwaarde": "geen verruiming, en liefst op termijn ook in Holten weer een rustige zondag", "fallback_standpunt": "De ChristenUnie is tegen winkels die op zondag open zijn: een gezamenlijke rustdag is waardevol, ook voor wie achter de kassa staat. Dit voorstel houdt verdere verruiming tegen, dus de fractie stemt voor."},
    "fvd": {"neiging": "tegen", "aandachtspunt": "vrijheid en zeggenschap van inwoners: FvD is voor zondagopenstelling in beide kernen", "voorwaarde": "zondagopenstelling in Rijssen en Holten, of in elk geval de inwoners zelf laten kiezen", "fallback_standpunt": "FvD vindt dat inwoners zelf mogen weten of ze op zondag boodschappen doen. De fractie wil zondagopenstelling in beide kernen en stemt tegen dit voorstel."},
    "vvd": {"neiging": "tegen", "aandachtspunt": "vrijheid voor ondernemers en klanten: de VVD is voor zondagopenstelling in beide kernen", "voorwaarde": "winkels mogen op zondag open in Rijssen en Holten, en de supermarkten in Holten mogen eerder open", "fallback_standpunt": "De VVD vindt dat ondernemers zelf moeten kunnen kiezen wanneer ze open zijn, in Holten én in Rijssen. Niemand wordt gedwongen op zondag te winkelen. De fractie stemt tegen dit voorstel."},
    "pro": {"neiging": "tegen", "aandachtspunt": "keuzevrijheid voor inwoners, met bescherming van werknemers: PRO is voor zondagopenstelling in beide kernen", "voorwaarde": "openstelling in beide kernen, en personeel mag niet worden verplicht op zondag te werken", "fallback_standpunt": "PRO is voor zondagopenstelling in Rijssen en Holten: inwoners mogen zelf kiezen. Wel moet het personeel beschermd worden: niemand mag gedwongen worden op zondag te werken."}
  }$j$::jsonb),
  '{feiten,0}', to_jsonb('In Holten mogen winkels op zondag open van 13.00 tot 18.00 uur; vooral de supermarkten doen dat.'::text)),
  '{raadsvoorstel}', to_jsonb('Het college stelt de raad voor de Winkeltijdenverordening niet te wijzigen en het verzoek van de supermarkten in Holten om op zondag eerder open te mogen af te wijzen. De huidige regeling blijft: in Holten op zondag open van 13.00 tot 18.00 uur, in Rijssen op zondag dicht.'::text)),
  '{pitch}', to_jsonb('In Holten mogen winkels op zondag open van 13.00 tot 18.00 uur, in Rijssen blijven ze dicht. De supermarkten in Holten willen eerder open, en een deel van de raad wil ook Rijssen op zondag open. Het college houdt vast aan het coalitieakkoord: alles blijft zoals het is. Maar niet elke coalitiepartij is daar even blij mee.'::text)),
  '{opties}', $j$[
    {"titel": "Instemmen: alles blijft zoals het is", "omschrijving": "Het coalitieakkoord wordt nagekomen en het compromis van na de kerkdiensten blijft. De supermarkten krijgen nee; wie meer ruimte wil, moet wachten."},
    {"titel": "Amendement: in Holten eerder open", "omschrijving": "Supermarkten in Holten mogen op zondag bijvoorbeeld vanaf 12.00 uur open. Tegemoetkoming aan ondernemers en recreanten, maar het raakt aan het compromis rond de kerkdiensten en aan het coalitieakkoord."},
    {"titel": "Amendement: ook in Rijssen open", "omschrijving": "Winkels mogen ook in Rijssen op zondagmiddag open. Gelijke regels voor beide kernen, maar voor een groot deel van de Rijssense gemeenschap een principiële grens."},
    {"titel": "Amendement: een proef met evaluatie", "omschrijving": "Een jaar lang ruimere openstelling, daarna evalueren met ondernemers, personeel, kerken en inwoners. Biedt ruimte om te leren, maar een proef wordt in de praktijk vaak blijvend."},
    {"titel": "Amendement: inwoners laten meebeslissen", "omschrijving": "Eerst een peiling onder inwoners voordat de raad besluit. Geeft draagvlak, maar een principiële kwestie laat zich niet altijd beslissen met een meerderheid van stemmen."}
  ]$j$::jsonb)
where id = 'zondagopenstelling-holten';
